<?php /** @var array $items @var array $tree @var array $pages @var array $redirects @var int $menuId @var string $location @var array $locationMeta @var \Core\Security\Csrf $csrf @var string $basePath */ ?>
<style>
.menu-location-tabs{display:flex;gap:.55rem;margin:0 0 1rem;padding:.35rem;border:1px solid var(--border);border-radius:.8rem;background:#f8fafc;width:max-content;max-width:100%}.menu-location-tab{padding:.65rem 1rem;border-radius:.58rem;color:var(--muted);font-weight:750;text-decoration:none}.menu-location-tab:hover{background:#fff;color:var(--text)}.menu-location-tab.is-active{background:#fff;color:var(--accent);box-shadow:0 4px 14px #0f172a12}.nav-workspace{display:grid;grid-template-columns:minmax(0,1.45fr) minmax(300px,.75fr);gap:1rem;align-items:start}.menu-canvas{background:linear-gradient(145deg,#f8fbfe,#eef5fa);border:1px solid var(--border);border-radius:.8rem;padding:1rem}.menu-tree,.menu-children{list-style:none;margin:0;padding:0}.menu-tree:empty:after{content:'This menu is empty. Add its first link from the panel.';display:block;padding:2rem 1rem;text-align:center;color:var(--muted)}.menu-children{margin:.55rem 0 0 2rem;padding-left:1rem;border-left:2px solid #c8d8e6;min-height:.7rem}.menu-node{margin:.55rem 0}.menu-card{display:flex;align-items:center;gap:.7rem;background:#fff;border:1px solid var(--border);border-radius:.65rem;padding:.65rem .75rem;box-shadow:0 5px 16px #0f172a0a}.menu-node.is-dragging{opacity:.35}.menu-node.is-over>.menu-card{border-color:var(--accent);box-shadow:0 0 0 3px #0ea5e91f}.drag-grip{cursor:grab;color:#71859a;font-size:1.15rem;padding:.25rem;user-select:none}.menu-summary{min-width:0;flex:1}.menu-summary strong,.menu-summary small{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.menu-summary small{color:var(--muted);margin-top:.15rem}.menu-actions{display:flex;gap:.3rem;align-items:center}.icon-btn{border:1px solid var(--border);background:#f8fafc;color:#334155;border-radius:.38rem;padding:.28rem .45rem;cursor:pointer}.tree-drop-root{border:2px dashed #bfd1df;border-radius:.6rem;padding:.65rem;text-align:center;color:var(--muted);margin-bottom:.65rem}.tree-drop-root.is-over{border-color:var(--accent);background:#e0f2fe}.link-source{display:grid;grid-template-columns:1fr 1fr;gap:.75rem}.source-panel{border:1px solid var(--border);border-radius:.6rem;padding:.8rem;background:#f8fafc}.source-panel label:first-child{margin-top:0}.target-options{display:grid;grid-template-columns:repeat(3,1fr);gap:.5rem}.target-options label{border:1px solid var(--border);border-radius:.5rem;padding:.55rem;background:#fff;margin:.4rem 0}.target-options input{width:auto}.editor-drawer{margin-top:.65rem;padding:.8rem;border:1px solid var(--border);border-radius:.6rem;background:#fff}.editor-drawer summary{cursor:pointer;font-weight:700}.menu-savebar{display:flex;justify-content:space-between;align-items:center;gap:1rem;margin-top:1rem;padding-top:1rem;border-top:1px solid var(--border)}
@media(max-width:1000px){.nav-workspace{grid-template-columns:1fr}}@media(max-width:700px){.link-source,.target-options{grid-template-columns:1fr}.menu-actions .move-label{display:none}.menu-children{margin-left:.75rem}}
</style>
<?php
$targetLabel = fn (string $target): string => match ($target) {'tab' => 'New tab', 'window' => 'New window', default => 'Same tab'};
$pageOptions = function (?int $selected = null) use ($pages): void { foreach ($pages as $page): ?><option value="<?= (int) $page['id'] ?>" <?= $selected === (int) $page['id'] ? 'selected' : '' ?>><?= e($page['title']) ?> — /<?= e($page['slug']) ?><?= $page['status'] !== 'published' ? ' (' . e($page['status']) . ')' : '' ?></option><?php endforeach; };
$renderTree = function (array $nodes) use (&$renderTree, $csrf, $pageOptions, $targetLabel, $location): void { foreach ($nodes as $item): ?>
<li class="menu-node" data-id="<?= (int) $item['id'] ?>" draggable="true">
<div class="menu-card"><span class="drag-grip" title="Drag to reorder or nest" aria-hidden="true">⋮⋮</span><div class="menu-summary"><strong><?= e($item['label']) ?></strong><small><?= !empty($item['page_id']) ? 'Page: ' . e($item['page_title'] ?? $item['url']) : e($item['url']) ?> · <?= e($targetLabel($item['target'] ?? 'self')) ?></small></div><div class="menu-actions"><button type="button" class="icon-btn move-up" title="Move up">↑ <span class="move-label">Up</span></button><button type="button" class="icon-btn move-down" title="Move down">↓ <span class="move-label">Down</span></button><button type="button" class="icon-btn indent" title="Make submenu">→</button><button type="button" class="icon-btn outdent" title="Move up one level">←</button></div></div>
<details class="editor-drawer"><summary>Edit link</summary><form method="post" class="menu-edit-form"><?= $csrf->field() ?><input type="hidden" name="location" value="<?= e_attr($location) ?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?= (int) $item['id'] ?>"><input type="hidden" name="parent_id" value="<?= e_attr((string) ($item['parent_id'] ?? '')) ?>"><input type="hidden" name="sort_order" value="<?= (int) $item['sort_order'] ?>"><label>Navigation label</label><input name="label" value="<?= e_attr($item['label']) ?>" required><div class="link-source"><div class="source-panel"><label>Website page</label><select name="page_id"><option value="">— custom link —</option><?php $pageOptions(!empty($item['page_id']) ? (int) $item['page_id'] : null); ?></select></div><div class="source-panel"><label>Custom URL</label><input name="url" value="<?= e_attr($item['url']) ?>" placeholder="/contact or https://example.com"></div></div><label>Open link</label><div class="target-options"><?php foreach (['self'=>'Same tab','tab'=>'New tab','window'=>'New window'] as $value=>$label): ?><label><input type="radio" name="target" value="<?= e_attr($value) ?>" <?= ($item['target'] ?? 'self') === $value ? 'checked' : '' ?>> <?= e($label) ?></label><?php endforeach; ?></div><button class="btn small">Save link</button></form><form method="post" style="margin-top:.5rem" onsubmit="return confirm('Remove this menu item? Its child links will move to the top level.')"><?= $csrf->field() ?><input type="hidden" name="location" value="<?= e_attr($location) ?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= (int) $item['id'] ?>"><button class="btn small danger">Remove</button></form></details>
<ul class="menu-children"><?php $renderTree($item['children'] ?? []); ?></ul></li>
<?php endforeach; };
?>
<nav class="menu-location-tabs" aria-label="Menu location">
<?php foreach ($locationMeta as $key => $meta): ?><a class="menu-location-tab <?= $location === $key ? 'is-active' : '' ?>" href="<?= e_attr($basePath) ?>/admin/navigation&amp;location=<?= e_attr($key) ?>" <?= $location === $key ? 'aria-current="page"' : '' ?>><?= e($meta['label']) ?></a><?php endforeach; ?>
</nav>
<div class="nav-workspace">
<section class="card"><div class="card-heading"><div><h2><?= e($locationMeta[$location]['label']) ?></h2><p class="muted"><?= $location === 'primary' ? 'These links appear in the website header.' : 'These links appear in the website footer.' ?> Drag links to reorder them, drop a link onto another card to make it a submenu, or use the arrow controls.</p></div><span class="badge"><?= count($items) ?> links</span></div><div class="menu-canvas" id="menu-canvas"><div class="tree-drop-root" id="root-drop">Drop here for top level</div><ul class="menu-tree" id="menu-tree"><?php $renderTree($tree); ?></ul></div><form method="post" id="tree-form"><?= $csrf->field() ?><input type="hidden" name="location" value="<?= e_attr($location) ?>"><input type="hidden" name="action" value="reorder"><input type="hidden" name="tree_json" id="tree-json"><div class="menu-savebar"><span class="muted" id="tree-status">Menu order is up to date.</span><button class="btn" id="save-tree" disabled>Save menu structure</button></div></form></section>
<aside class="card"><h2 style="margin-top:0">Add a <?= $location === 'primary' ? 'header' : 'footer' ?> link</h2><p class="muted">Choose an existing page by name or enter a custom internal/external URL.</p><form method="post"><?= $csrf->field() ?><input type="hidden" name="location" value="<?= e_attr($location) ?>"><input type="hidden" name="action" value="add"><input type="hidden" name="parent_id" value=""><input type="hidden" name="sort_order" value="<?= count($items) ?>"><label>Navigation label</label><input name="label" required placeholder="About us"><div class="source-panel"><label>Website page</label><select name="page_id" id="new-page"><option value="">— use a custom link —</option><?php $pageOptions(); ?></select><label>Custom URL</label><input name="url" id="new-url" placeholder="/contact or https://example.com"></div><label>Open link</label><div class="target-options"><?php foreach (['self'=>'Same tab','tab'=>'New tab','window'=>'New window'] as $value=>$label): ?><label><input type="radio" name="target" value="<?= e_attr($value) ?>" <?= $value === 'self' ? 'checked' : '' ?>> <?= e($label) ?></label><?php endforeach; ?></div><button class="btn">Add to <?= $location === 'primary' ? 'header' : 'footer' ?> menu</button></form></aside>
</div>
<div class="card"><h2 style="margin-top:0">Redirects</h2><?php if ($redirects === []): ?><p class="muted">No redirects. Add one when a page moves so old links keep working.</p><?php else: ?><table><tr><th>Source</th><th>Target</th><th>Code</th><th>Hits</th><th></th></tr><?php foreach ($redirects as $rd): ?><tr><td><code><?= e($rd['source']) ?></code></td><td><code><?= e($rd['target']) ?></code></td><td><?= (int) $rd['status_code'] ?></td><td><?= (int) $rd['hits'] ?></td><td><form method="post"><?= $csrf->field() ?><input type="hidden" name="location" value="<?= e_attr($location) ?>"><input type="hidden" name="action" value="redirect_delete"><input type="hidden" name="id" value="<?= (int) $rd['id'] ?>"><button class="btn small danger">Remove</button></form></td></tr><?php endforeach; ?></table><?php endif; ?><details><summary class="btn secondary">Add redirect</summary><form method="post" style="margin-top:1rem"><?= $csrf->field() ?><input type="hidden" name="location" value="<?= e_attr($location) ?>"><input type="hidden" name="action" value="redirect_add"><div class="inline-fields"><div><label>Source path</label><input name="source" placeholder="/old-page" required></div><div><label>Target</label><input name="target" placeholder="/new-page" required></div><div><label>Code</label><select name="status_code"><option>301</option><option>302</option><option>307</option><option>308</option></select></div></div><button class="btn">Add redirect</button></form></details></div>
<script>
(() => {
  const tree=document.getElementById('menu-tree'), rootDrop=document.getElementById('root-drop'), save=document.getElementById('save-tree'), status=document.getElementById('tree-status'), json=document.getElementById('tree-json'); let dragging=null;
  const serialize=list=>[...list.children].filter(n=>n.matches('.menu-node')).map(n=>({id:Number(n.dataset.id),children:serialize(n.querySelector(':scope > .menu-children'))}));
  const changed=()=>{json.value=JSON.stringify(serialize(tree));save.disabled=false;status.textContent='Unsaved menu structure changes.';};
  const wire=node=>{node.addEventListener('dragstart',e=>{dragging=node;node.classList.add('is-dragging');e.dataTransfer.effectAllowed='move';});node.addEventListener('dragend',()=>{node.classList.remove('is-dragging');dragging=null;document.querySelectorAll('.is-over').forEach(n=>n.classList.remove('is-over'));});node.querySelector(':scope > .menu-card').addEventListener('dragover',e=>{e.preventDefault();if(dragging&&dragging!==node&&!dragging.contains(node))node.classList.add('is-over');});node.querySelector(':scope > .menu-card').addEventListener('dragleave',()=>node.classList.remove('is-over'));node.querySelector(':scope > .menu-card').addEventListener('drop',e=>{e.preventDefault();node.classList.remove('is-over');if(dragging&&dragging!==node&&!dragging.contains(node)){node.querySelector(':scope > .menu-children').appendChild(dragging);changed();}});
    node.querySelector('.move-up').onclick=()=>{const prev=node.previousElementSibling;if(prev){node.parentElement.insertBefore(node,prev);changed();}};node.querySelector('.move-down').onclick=()=>{const next=node.nextElementSibling;if(next){node.parentElement.insertBefore(next,node);changed();}};node.querySelector('.indent').onclick=()=>{const prev=node.previousElementSibling;if(prev){prev.querySelector(':scope > .menu-children').appendChild(node);changed();}};node.querySelector('.outdent').onclick=()=>{const parentNode=node.parentElement.closest('.menu-node');if(parentNode){parentNode.parentElement.insertBefore(node,parentNode.nextElementSibling);changed();}};
  };
  tree.querySelectorAll('.menu-node').forEach(wire);rootDrop.addEventListener('dragover',e=>{e.preventDefault();rootDrop.classList.add('is-over');});rootDrop.addEventListener('dragleave',()=>rootDrop.classList.remove('is-over'));rootDrop.addEventListener('drop',e=>{e.preventDefault();rootDrop.classList.remove('is-over');if(dragging){tree.appendChild(dragging);changed();}});json.value=JSON.stringify(serialize(tree));document.getElementById('tree-form').addEventListener('submit',()=>json.value=JSON.stringify(serialize(tree)));
  const page=document.getElementById('new-page'),url=document.getElementById('new-url');page.addEventListener('change',()=>{url.disabled=page.value!=='';if(page.value!=='')url.value='';});
})();
</script>
